//! T-3703 (arc-011 P-15, B-5) slice A: AL-20 against the 06a 2.4.c.1 vectors, and E-42 (forged or malformed
//! revocation lists are refused; at least 10^5 mutated lists).
//!
//! Fixture: `tests/fixtures/signed-state-vectors.json`, generated by `gen-signed-state-vectors.py` (RFC 8032 test
//! key 1, never an estate key).

use ed25519_dalek::{Signer, SigningKey, VerifyingKey};
use serde_json::Value;
use termlink_session::signed_state::{self as ss, J, Refused};

fn fixture() -> Value {
    let p = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/signed-state-vectors.json");
    serde_json::from_str(&std::fs::read_to_string(p).expect("vector file")).expect("vector JSON")
}

fn key(f: &Value) -> SigningKey {
    let seed: [u8; 32] = ss::unhex_lower(f["seed_rfc8032_test1"].as_str().unwrap()).unwrap().try_into().unwrap();
    SigningKey::from_bytes(&seed)
}

fn vector<'a>(f: &'a Value, id: &str) -> &'a Value {
    f["vectors"].as_array().unwrap().iter().find(|v| v["id"] == id).unwrap()
}

fn text_of(o: &J) -> String {
    serde_json::to_string(&o.to_serde()).unwrap()
}

#[test]
fn e42_vectors_reproduce_byte_exactly() {
    let f = fixture();
    let k = key(&f);
    assert_eq!(ss::hex(k.verifying_key().as_bytes()), f["public_key"].as_str().unwrap());
    assert_eq!(f["public_key"], "d75a980182b10ab7d54bfed3c964073a0ee172f3daa62325af021a68f707511a", "06a 2.4.c.1 key");
    // The 06a table values, written here as well so a regenerated fixture cannot move them silently.
    let pinned = [
        ("V-REV-1", 436, "044cfb1cf8c79cc60832cce9145895ff1bca2338d28c447823e687a3b6fe5767", "02739ad55f80d541"),
        ("V-HEAD-1", 151, "cc363257e39103a2d922e6ec0000810659449f3c0098e0471ab8c9932f2b24dd", "ea99514e54465969"),
        ("V-FWD-1", 320, "7a7e9bf16ae3f54de6f1007b0ec917cac6f613c9dd5ce7eed6e9a38764af421d", "29495852a7b15ef3"),
    ];
    for (id, len, dg, sig16) in pinned {
        let v = vector(&f, id);
        assert_eq!(v["canonical_len"], len, "{id}");
        assert_eq!(v["digest"], dg, "{id}");
        assert!(v["signature"].as_str().unwrap().starts_with(sig16), "{id}");
    }
    for v in f["vectors"].as_array().unwrap() {
        let id = v["id"].as_str().unwrap();
        let o = J::from_serde(&v["object"]).unwrap();
        let c = ss::canonical(&o).unwrap();
        assert_eq!(String::from_utf8(c.clone()).unwrap(), v["canonical"].as_str().unwrap(), "{id} canonical");
        assert_eq!(c.len() as u64, v["canonical_len"].as_u64().unwrap(), "{id} length");
        assert_eq!(ss::digest(&o).unwrap(), v["digest"].as_str().unwrap(), "{id} digest");
        let sealed = ss::seal(&k, o).unwrap();
        assert_eq!(sealed.get("signature").unwrap().as_str().unwrap(), v["signature"].as_str().unwrap(), "{id} sig");
        let schema = v["object"]["schema"].as_str().unwrap();
        ss::parse_and_verify(text_of(&sealed).as_bytes(), &k.verifying_key(), schema).unwrap();
        // The canonical text itself also parses back to the same canonical bytes.
        let back = ss::parse_strict(v["canonical"].as_str().unwrap().as_bytes()).unwrap();
        assert_eq!(ss::canonical(&back).unwrap(), c, "{id} round trip");
    }
}

#[test]
fn e42_v_rev_2_reencoding_is_the_same_object() {
    let f = fixture();
    let v = vector(&f, "V-REV-1");
    let alt = ss::parse_strict(v["alt_text"].as_str().unwrap().as_bytes()).unwrap();
    assert_eq!(String::from_utf8(ss::canonical(&alt).unwrap()).unwrap(), v["canonical"].as_str().unwrap());
    assert_eq!(ss::digest(&alt).unwrap(), v["digest"].as_str().unwrap());
}

#[test]
fn e42_negative_vectors_are_refused() {
    let f = fixture();
    for n in f["negative"].as_array().unwrap() {
        let id = n["id"].as_str().unwrap();
        let r = ss::parse_strict(n["text"].as_str().unwrap().as_bytes());
        match n["refusal"].as_str().unwrap() {
            "number" => assert!(matches!(r, Err(Refused::Number(_))), "{id}: {r:?}"),
            "duplicate" => assert!(matches!(r, Err(Refused::Duplicate(_))), "{id}: {r:?}"),
            other => panic!("unknown refusal {other}"),
        }
    }
    // V-NEG-3: V-REV-1 signed over the bare digest (no domain prefix) does not verify.
    let k = key(&f);
    let v = vector(&f, "V-REV-1");
    let bare = v["signature_without_domain"].as_str().unwrap();
    assert!(bare.starts_with("3b0af0c2379828c0e02d6a1ee48ffa95"), "06a V-NEG-3 prefix");
    let mut o = J::from_serde(&v["object"]).unwrap();
    o.set("digest", J::Str(v["digest"].as_str().unwrap().into()));
    o.set("signature", J::Str(bare.into()));
    assert_eq!(ss::verify(&k.verifying_key(), &o, None), Err(Refused::BadSignature));
}

// ---------------------------------------------------------------------------------------------------------------
// E-42 fuzz: at least 10^5 mutated lists. Oracle: a list is accepted only if its canonical form equals the valid
// one's; every semantically equal re-encoding is accepted; nothing panics.

struct Rng(u64);
impl Rng {
    fn next(&mut self) -> u64 {
        let mut x = self.0;
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        self.0 = x;
        x
    }
    fn below(&mut self, n: usize) -> usize {
        (self.next() % n.max(1) as u64) as usize
    }
}

/// Serialise `v` with a random member order, random whitespace and random `\u` escapes: the same object.
fn reencode(r: &mut Rng, v: &J, out: &mut String) {
    let ws = |r: &mut Rng, out: &mut String| {
        for _ in 0..r.below(3) {
            out.push([' ', '\n', '\t', '\r'][r.below(4)]);
        }
    };
    ws(r, out);
    match v {
        J::Null => out.push_str("null"),
        J::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
        J::Int(i) => out.push_str(&i.to_string()),
        J::Str(s) => {
            out.push('"');
            for ch in s.chars() {
                match ch {
                    '"' => out.push_str("\\\""),
                    '\\' => out.push_str("\\\\"),
                    c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04X}", c as u32)),
                    c if c.is_ascii_alphanumeric() && r.below(8) == 0 => out.push_str(&format!("\\u{:04x}", c as u32)),
                    '/' if r.below(2) == 0 => out.push_str("\\/"),
                    c => out.push(c),
                }
            }
            out.push('"');
        }
        J::Arr(a) => {
            out.push('[');
            for (n, x) in a.iter().enumerate() {
                if n > 0 {
                    out.push(',');
                }
                reencode(r, x, out);
            }
            out.push(']');
        }
        J::Obj(m) => {
            let mut idx: Vec<usize> = (0..m.len()).collect();
            for i in (1..idx.len()).rev() {
                idx.swap(i, r.below(i + 1));
            }
            out.push('{');
            for (n, &i) in idx.iter().enumerate() {
                if n > 0 {
                    out.push(',');
                }
                ws(r, out);
                let mut k = String::new();
                reencode(r, &J::Str(m[i].0.clone()), &mut k);
                out.push_str(k.trim_start());
                ws(r, out);
                out.push(':');
                reencode(r, &m[i].1, out);
            }
            ws(r, out);
            out.push('}');
        }
    }
    ws(r, out);
}

/// A structural change of the object (a different object, so it must be refused).
fn change(r: &mut Rng, o: &mut J, other: &SigningKey) {
    match r.below(7) {
        0 => o.set("seq", J::Int(o.get("seq").and_then(J::as_int).unwrap_or(0) + 1 + r.below(3) as i64)),
        1 => {
            if let J::Obj(m) = o {
                let i = r.below(m.len());
                m.remove(i);
            }
        }
        2 => o.set("prev_digest", J::Str("1".repeat(64))),
        3 => {
            let up = o.get("signature").and_then(J::as_str).unwrap_or("").to_ascii_uppercase();
            o.set("signature", J::Str(up));
        }
        4 => {
            // Re-signed by another key: well formed, wrong signer.
            let d = ss::digest(o).unwrap();
            o.set("digest", J::Str(d.clone()));
            let s = other.sign(&ss::signing_input("termlink.revocation/1", &d));
            o.set("signature", J::Str(ss::hex(&s.to_bytes())));
        }
        5 => {
            if let Some(J::Arr(es)) = match o {
                J::Obj(m) => m.iter_mut().find(|(k, _)| k == "entries").map(|(_, v)| v),
                _ => None,
            } {
                if let Some(J::Obj(e)) = es.first_mut() {
                    let i = r.below(e.len());
                    e[i].1 = J::Str("ed25519:".to_string() + &"0".repeat(64));
                }
            }
        }
        _ => o.set("extra", J::Int(r.below(100) as i64)),
    }
}

/// A byte-level change of the text (most are syntax errors; some are other objects).
fn corrupt(r: &mut Rng, t: &mut Vec<u8>) {
    if t.is_empty() {
        return;
    }
    let at = r.below(t.len());
    match r.below(6) {
        0 => t[at] = (r.next() & 0xff) as u8,
        1 => {
            let end = (at + 1 + r.below(8)).min(t.len());
            t.drain(at..end);
        }
        2 => {
            let tok: &[u8] = [&b","[..], b"\"seq\":7,", b"1.0", b"1e0", b"-0", b"\"x\"", b"}", b"\\u0000", b"\xc3"]
                [r.below(9)];
            t.splice(at..at, tok.iter().copied());
        }
        3 => {
            // A duplicate key right after the first brace.
            if let Some(p) = t.iter().position(|&c| c == b'{') {
                t.splice(p + 1..p + 1, b"\"seq\":7,".iter().copied());
            }
        }
        4 => {
            // Rewrite the first integer as a fraction or exponent.
            if let Some(p) = t.windows(6).position(|w| w == b"\"seq\":") {
                let form: &[u8] = [&b"7.0"[..], b"7e0", b"7E0", b"07"][r.below(4)];
                let s = p + 6;
                let e = s + t[s..].iter().take_while(|c| c.is_ascii_digit()).count();
                t.splice(s..e, form.iter().copied());
            }
        }
        _ => t.truncate(at),
    }
}

#[test]
fn e42_fuzz_100k_mutated_lists() {
    let f = fixture();
    let k = key(&f);
    let pk: VerifyingKey = k.verifying_key();
    let other = SigningKey::from_bytes(&[42u8; 32]);
    let v = vector(&f, "V-REV-1");
    let valid = ss::seal(&k, J::from_serde(&v["object"]).unwrap()).unwrap();
    let want = ss::canonical(&valid).unwrap();
    let mut r = Rng(0x7e57_3703_0000_0001);
    let (mut accepted, mut refused, mut equal_cases) = (0u64, 0u64, 0u64);
    const N: u64 = 100_000;
    for _ in 0..N {
        let mut obj = valid.clone();
        let structural = r.below(4) == 0;
        if structural {
            change(&mut r, &mut obj, &other);
        }
        let mut s = String::new();
        reencode(&mut r, &obj, &mut s);
        let mut bytes = s.into_bytes();
        let corrupted = r.below(2) == 0;
        if corrupted {
            corrupt(&mut r, &mut bytes);
        }
        match ss::parse_and_verify(&bytes, &pk, "termlink.revocation/1") {
            Ok(o) => {
                accepted += 1;
                assert_eq!(ss::canonical(&o).unwrap(), want, "accepted a list not canonically equal to the valid one");
                assert_eq!(o.get("signature"), valid.get("signature"));
            }
            Err(_) => {
                refused += 1;
                assert!(structural || corrupted, "a semantically equal re-encoding was refused: {}",
                    String::from_utf8_lossy(&bytes));
            }
        }
        if !structural && !corrupted {
            equal_cases += 1;
        }
    }
    assert_eq!(accepted + refused, N);
    assert!(equal_cases > 30_000 && refused > 30_000, "both classes exercised: {equal_cases} equal, {refused} refused");
    println!("E-42 PASS: {N} mutated lists, {accepted} accepted (all canonically equal), {refused} refused");
}
